        cs_coroutine.stop(self.__showRewardDialogCoroutine)
        self.__showRewardDialogCoroutine = nil
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        playerComponent:StopRewardsSpecialDialogCo()
    end
end

function UIEntrustEndDialog:FillSelf()
    local questType = GoodsUtils.GetIdType(self.entrustQueueData.questId, Constants.IDArea.Quests)
    local questData = QuestConfMgr:GetInstance():GetQuestVoById(self.entrustQueueData.questId)
    CfUtils.FillText(self.questDes, questData.name)

    --总时间
    local time = checkNumber(questData.time) * self.entrustQueueData.questSum
    local StoreConstants = import('Game.UI.Store.StoreConstants')
    local monthCardNum = 0
    if checkNumber(self.entrustQueueData.isMonthCard) == 1 then
        --monthCardNum = checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.AutoTimes))
        --由于月卡过期后无法取得月卡数据，跟策划商量确认后取月卡奖励表第一行的数据
        --monthCardNum = CfUtils.GetWholeVo(AutoIds.IdSetting602, "MonthCardRewardVo")[1].privilege["autoTime"]
    end
    if monthCardNum == 0 then
        monthCardNum = 1
    end
    time = time * monthCardNum
    if TimeZoneUtils.UtcSeconds < checkNumber(self.entrustQueueData.expirationTime) then
        time = time - (checkNumber(self.entrustQueueData.expirationTime) - TimeZoneUtils.UtcSeconds)
    end
    CfUtils.FillText(self.time, CfUtils.GetTimeHMS(time))
    CfUtils.FillText(self.allNum, self:GetAllEntrustTime(self.entrustQueueData))

    self:FillPlaerInfo()
    self:FillRewards()
end

--绘制人物信息
function UIEntrustEndDialog:FillPlaerInfo()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    self.PlayerNode.Env:FreshBaseUI()
    CfUtils.FillText(self.TxtName, tostring(playerComponent.playerDojo.playerName))
    CfUtils.FillText(self.TxtLv, tostring(playerComponent.playerDojo.level))
    --经验
    local playerExp = CardConfMgr:GetInstance():GetPlayerExpByLevelId(checkInt(playerComponent.playerDojo.level))
    local nextExp = CardConfMgr:GetInstance():GetPlayerExpByLevelId(checkInt(playerComponent.playerDojo.level) + 1)
    self.SliderExp.value = (checkInt(playerComponent.playerDojo.mainExp) - checkInt(playerExp.totalExp)) / checkInt(nextExp.exp)
    CfUtils.FillText(self.ExpProgressText, string.format('%d/%d', (checkInt(playerComponent.playerDojo.mainExp) - checkInt(playerExp.totalExp)), checkInt(nextExp.exp)))
end

--绘制奖励
function UIEntrustEndDialog:FillRewards()
    if not self.rewards then
        return
    end
    local playerExpGoodId = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 15).num
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerExpGoodNum =  playerComponent.playerDojo.mainExp - playerComponent:GetExpBefore()
    local rewrdArr = {}
    if playerExpGoodNum > 0 then
        table.insert(rewrdArr, {
            goodsId = playerExpGoodId,
            num = playerExpGoodNum
        })
    end
    for k, v in pairs(self.rewards) do
        table.insert(rewrdArr, v)
    end
    --print("endRewardData------>>"..table.dump(rewrdArr, nil, 3))
    --local scr = CfUtils.GetLuaScr(self.rewardPar, UIFightReardsNode)
    --if scr then
    --    scr:Refersh(rewrdArr, 0.82, true)
    --    scr:RefershSpacing(-30)
    --end
    --self.Content.sizeDelta = Vector2(#rewrdArr * 187, self.Content.sizeDelta.y)
    ----不改变现有结构的情况下修改道具显示节点
    for i = 1, #rewrdArr do
        local go
        go = self.goodNodeList[i]
        if not go then
            go = CfUtils.InstantiateGo(self.GoodNode, self.rewardPar.gameObject)
            go.name = "GoodNode"..i
            self.goodNodeList[i] = go.gameObject
        end
        local goEnv = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
        local item = rewrdArr[i]
        local _checkGoodsIdForSignNum = function(goodsId, goodsNum)
            local idType = GoodsUtils.GetIdType(goodsId)
            if idType == Constants.IDType.Equipment or idType == Constants.IDType.EquipmentCore then return end
            return goodsNum
        end
        local num = _checkGoodsIdForSignNum(item.goodsId, item.num)
        local goodsParaList = not IsNull(num)
                and { goodsId = item.goodsId, isShowNo = true, text = string.format("x%s", math.abs(num)), dojo = item.playerEquipment }
                or { goodsId = item.goodsId, text = tostring(num), dojo = item.playerEquipment }
        goEnv:Reload(goodsParaList)
        goEnv:SetSanXingFlagShow(isSet(item, "isStarReward") and item.isStarReward > 0)
        if isSet(item, "isStarReward") and item.isStarReward > 0 then
            goEnv:SetBonusText(localize("三星奖励"),false, "#ffd646")
        end
        goEnv:SetClickButtonAction(
                function(goodsId, uId)
                    GameUtils.ShowResultTips(go.gameObject, goodsId, uId)
                end)
        KTool.SetActive(go, true)
    end
end

---GetAllEntrustTime  结算时候计算总共委托了多少场
---@param entrustData EntrustTeamDojo
function UIEntrustEndDialog:GetAllEntrustTime(entrustData)
    local curEntrustTime = 0
    if not entrustData then
        return curEntrustTime
    end

    if checkNumber(entrustData.questId) ~= 0 then  
        local questData = QuestConfMgr:GetInstance():GetQuestVoById(entrustData.questId)
        if not questData then
            return curEntrustTime
        end
        if TimeZoneUtils.UtcSeconds >= checkNumber(entrustData.expirationTime) then
            curEntrustTime = entrustData.questSum
        else
            local time = checkNumber(entrustData.expirationTime) - TimeZoneUtils.UtcSeconds
            local StoreConstants = import('Game.UI.Store.StoreConstants')
            local monthCardNum = 0
            --if checkNumber(entrustData.isMonthCard) == 1 then
            --    --monthCardNum = checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.AutoTimes))
            --    --由于月卡过期后无法取得月卡数据，跟策划商量确认后取月卡奖励表第一行的数据
            --    monthCardNum = CfUtils.GetWholeVo(AutoIds.IdSetting602, "MonthCardRewardVo")[1].privilege["autoTime"]
            --end
            if monthCardNum == 0 then
                monthCardNum = 1
            end
            curEntrustTime = entrustData.questSum - (math.ceil(time / (checkNumber(questData.time) * monthCardNum)))
        end
    end 
    return curEntrustTime
end

